<template>
<v-app class="admin-app"><div class="admin-shell"><aside class="sidebar"><router-link to="/" aria-label="Volver al catálogo"><AppBrand compact /></router-link><p class="nav-label">ADMINISTRACIÓN</p><nav><button v-for="item in sections" :key="item.id" :class="{active:section===item.id}" @click="section=item.id"><v-icon size="19">{{ item.icon }}</v-icon>{{ item.title }}<v-icon v-if="section===item.id" size="15" class="nav-arrow">mdi-chevron-right</v-icon></button></nav><div class="sidebar-bottom"><span class="admin-avatar">A</span><div><strong>Administrador</strong><small>Acceso general</small></div><button aria-label="Cerrar sesión" @click="logout"><v-icon size="19">mdi-logout</v-icon></button></div></aside>
<main class="admin-main"><header class="topbar"><span>{{ BRAND.appName }} <span class="breadcrumb">/ {{ current.title }}</span></span><router-link to="/">Ver catálogo <v-icon size="16">mdi-arrow-top-right</v-icon></router-link></header><div class="admin-content"><div class="page-heading"><div><p class="eyebrow">TU PLATAFORMA, EN UN SOLO LUGAR</p><h1>{{ current.heading }}</h1><p>{{ current.description }}</p></div><v-btn v-if="section==='commerces' || section==='overview'" color="#234e3d" flat rounded="lg" prepend-icon="mdi-plus" @click="openCommerce()">Nuevo comercio</v-btn><v-btn v-if="section==='users'" color="#234e3d" flat rounded="lg" prepend-icon="mdi-plus" @click="userDialog=true">Nueva cuenta</v-btn></div>
<v-alert v-if="error" type="error" variant="tonal" class="mb-5" closable @click:close="error=''">{{ error }} <button @click="load">Reintentar</button></v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-5" closable @click:close="success=''">{{ success }}</v-alert><v-progress-linear v-if="loading" indeterminate color="#748265" class="mb-5" />
<template v-if="section==='overview'"><div class="stats"><div v-for="s in stats" :key="s.label" class="stat-card"><div><span>{{ s.label }}</span><v-icon size="20">{{ s.icon }}</v-icon></div><strong>{{ loading ? '—' : s.value }}</strong><p>{{ s.note }}</p></div></div><div class="overview-grid"><section class="surface"><div class="surface-heading"><h2>Comercios recientes</h2><button @click="section='commerces'">Ver todos ↗</button></div><div v-if="!commerces.length" class="empty"><span class="empty-symbol"><v-icon size="30">mdi-storefront-outline</v-icon></span><h3>El primer comercio empieza contigo.</h3><p>Crea una cuenta de comerciante y asígnale su negocio.</p><v-btn variant="outlined" color="#234e3d" rounded="lg" @click="section='users';userDialog=true">Crear cuenta de comerciante</v-btn></div><button v-for="c in commerces.slice(0,5)" :key="c.id" class="commerce-row" @click="openCommerce(c)"><span class="store-icon"><v-icon>mdi-store-outline</v-icon></span><span><strong>{{ c.name }}</strong><small>{{ c.market }} · {{ c.stall }}</small></span><v-icon size="18">mdi-arrow-top-right</v-icon></button></section><section class="platform-card"><p class="eyebrow">CONSTRUYENDO COMERCIO LOCAL</p><h2>Personas detrás<br>de cada negocio.</h2><p>Asigna cada comercio a su propietario. Sus productos e inventario estarán disponibles únicamente para su cuenta.</p><div class="platform-step"><v-icon>mdi-account-key-outline</v-icon><span>Permisos por cuenta y comercio</span></div><div class="platform-step"><v-icon>mdi-package-variant-closed</v-icon><span>Productos e inventario conectados</span></div><div class="roadmap-note">Las suscripciones y los pedidos se incorporarán en las siguientes etapas.</div></section></div></template>
<section v-else-if="section==='commerces'" class="surface"><div class="list-tools"><h2>Todos los comercios <span>{{ commerces.length }}</span></h2><input v-model="search" placeholder="Buscar comercio…" aria-label="Buscar comercio" /></div><div class="table-scroll"><table><thead><tr><th>Comercio</th><th>Mercado / ubicación</th><th>Propietario</th><th>Contacto</th><th></th></tr></thead><tbody><tr v-for="c in filteredCommerces" :key="c.id"><td><strong>{{ c.name }}</strong><small>Comercio #{{ c.id }}</small></td><td>{{ c.market }}<small>{{ c.stall }}</small></td><td>{{ ownerLabel(c.owner_id) }}</td><td>{{ c.phone }}</td><td><button class="table-action" @click="openCommerce(c)">Gestionar ↗</button></td></tr><tr v-if="!filteredCommerces.length"><td colspan="5" class="empty-cell">{{ search ? 'No hay coincidencias.' : 'Todavía no hay comercios registrados.' }}</td></tr></tbody></table></div></section>
<section v-else-if="section==='users'" class="surface"><div class="list-tools"><h2>Cuentas de la plataforma <span>{{ users.length }}</span></h2><input v-model="search" placeholder="Buscar cuenta…" aria-label="Buscar cuenta" /></div><div class="table-scroll"><table><thead><tr><th>Cuenta</th><th>Acceso</th><th>Comercios asignados</th><th>Estado</th></tr></thead><tbody><tr v-for="u in filteredUsers" :key="u.id"><td><strong>{{ u.admin ? 'Administrador principal' : u.email }}</strong><small>Usuario #{{ u.id }}</small></td><td>{{ u.admin ? 'Administrador' : u.merchant ? 'Comerciante' : 'Cliente' }}</td><td>{{ commerces.filter(c=>c.owner_id===u.id).length }}</td><td><span class="status-pill">{{ u.state===1 ? 'Activo' : 'Inactivo' }}</span></td></tr><tr v-if="!filteredUsers.length"><td colspan="4" class="empty-cell">No hay coincidencias.</td></tr></tbody></table></div></section>
<section v-else class="surface"><div class="list-tools"><h2>Productos del mercado <span>{{ summary.products }}</span></h2><select v-model="productCommerce" aria-label="Filtrar productos por comercio" @change="loadProducts"><option value="">Todos los comercios</option><option v-for="c in commerces" :key="c.id" :value="c.id">{{ c.name }}</option></select></div><p class="list-caption">Consulta de los últimos 200 productos. Cada propietario administra su inventario desde Mi negocio.</p><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Comercio</th><th>Precio</th><th>Existencias</th><th>Catálogo</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td><strong>{{ p.name }}</strong><small>{{ p.category }}</small></td><td>{{ p.commerce?.name }}</td><td>{{ money(p.price) }} / {{ p.unit }}</td><td>{{ Number(p.stock) }} {{ p.unit }}</td><td>{{ p.active ? 'Publicado' : 'Oculto' }}</td></tr><tr v-if="!products.length"><td colspan="5" class="empty-cell">No hay productos para mostrar.</td></tr></tbody></table></div></section>
<footer class="panel-footer">{{ BRAND.name }} · Administración general<span>{{ BRAND.market }}</span></footer></div></main></div>
<v-dialog v-model="commerceDialog" max-width="570" :persistent="saving"><v-card rounded="xl" :title="commerce.id ? 'Gestionar comercio' : 'Registrar comercio'"><v-card-text><v-form id="admin-commerce" @submit.prevent="saveCommerce"><v-text-field v-model="commerce.name" label="Nombre del comercio" required maxlength="180" variant="outlined"/><v-select v-model="commerce.owner_id" :items="ownerOptions" item-title="label" item-value="id" label="Propietario del comercio" required variant="outlined"/><p v-if="!ownerOptions.length" class="mb-4">Primero crea una cuenta de comerciante en Usuarios.</p><v-text-field v-model="commerce.market" label="Mercado o zona" required maxlength="180" variant="outlined"/><v-text-field v-model="commerce.stall" label="Puesto o dirección" required maxlength="180" variant="outlined"/><v-text-field v-model="commerce.phone" label="Teléfono" required maxlength="30" variant="outlined"/><p class="dialog-note">El propietario seleccionado podrá administrar los productos y el inventario de este comercio.</p></v-form></v-card-text><v-card-actions><v-btn :disabled="saving" @click="commerceDialog=false">Cancelar</v-btn><v-btn form="admin-commerce" type="submit" :loading="saving" color="#234e3d">Guardar comercio</v-btn></v-card-actions></v-card></v-dialog>
<v-dialog v-model="userDialog" max-width="530" :persistent="saving"><v-card rounded="xl" title="Nueva cuenta"><v-card-text><v-form id="admin-user" @submit.prevent="saveUser"><v-select v-model="newUser.type" :items="[{title:'Comerciante',value:'merchant'},{title:'Cliente',value:'customer'}]" label="Tipo de cuenta" variant="outlined"/><v-text-field v-model="newUser.email" label="Correo electrónico" type="email" required maxlength="254" autocomplete="off" variant="outlined"/><v-text-field v-model="newUser.password" label="Contraseña inicial" type="password" required minlength="8" maxlength="128" autocomplete="new-password" variant="outlined"/><p class="dialog-note">Usa al menos 8 caracteres. La contraseña no se mostrará en el listado de usuarios.</p></v-form></v-card-text><v-card-actions><v-btn :disabled="saving" @click="userDialog=false">Cancelar</v-btn><v-btn form="admin-user" type="submit" :loading="saving" color="#234e3d">Crear cuenta</v-btn></v-card-actions></v-card></v-dialog><v-snackbar v-model="showError" color="error" :timeout="8000">{{ error }}</v-snackbar>
</v-app>
</template>
<script setup>
import {ref,computed,onMounted,watch} from 'vue';
import {useRouter} from 'vue-router';
import AppBrand from '@/components/AppBrand.vue';
import {BRAND} from '@/config/brand';
import api from '@/services/mercado.services';
const router=useRouter(), section=ref('overview'),search=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),showError=ref(false);
const summary=ref({commerces:0,products:0,published:0,users:0}),commerces=ref([]),users=ref([]),products=ref([]),productCommerce=ref('');
const commerceDialog=ref(false),userDialog=ref(false),commerce=ref({}),newUser=ref({type:'merchant',email:'',password:''});
const sections=[{id:'overview',title:'Vista general',icon:'mdi-view-dashboard-outline',heading:'Todo empieza aquí.',description:'Una vista general de los comercios y las personas que hacen crecer tu plataforma.'},{id:'commerces',title:'Comercios',icon:'mdi-storefront-outline',heading:'Comercios que conectan.',description:'Registra negocios y asigna a cada uno su propietario.'},{id:'users',title:'Usuarios',icon:'mdi-account-group-outline',heading:'Tu comunidad.',description:'Crea cuentas de comerciantes y clientes, y consulta sus accesos.'},{id:'products',title:'Productos',icon:'mdi-package-variant-closed',heading:'Lo que ofrece tu mercado.',description:'Consulta los productos publicados por todos los comercios.'}];
const current=computed(()=>sections.find(s=>s.id===section.value));
const stats=computed(()=>[{label:'Comercios',value:summary.value.commerces,icon:'mdi-store-outline',note:'Negocios registrados'},{label:'Usuarios',value:summary.value.users,icon:'mdi-account-outline',note:'Cuentas en la plataforma'},{label:'Productos',value:summary.value.products,icon:'mdi-package-variant-closed',note:'En todos los comercios'},{label:'En el catálogo',value:summary.value.published,icon:'mdi-eye-outline',note:'Productos publicados'}]);
const filteredCommerces=computed(()=>commerces.value.filter(c=>`${c.name} ${c.market} ${c.stall}`.toLowerCase().includes(search.value.toLowerCase())));
const filteredUsers=computed(()=>users.value.filter(u=>`${u.admin?'Administrador principal':u.email} ${u.id}`.toLowerCase().includes(search.value.toLowerCase())));
const ownerOptions=computed(()=>users.value.filter(u=>u.state===1).map(u=>({...u,label:u.admin?'Administrador principal':u.email})));
const ownerLabel=id=>ownerOptions.value.find(u=>u.id===id)?.label || `Usuario #${id}`;
const money=v=>new Intl.NumberFormat('es-SV',{style:'currency',currency:'USD'}).format(Number(v));
function report(e){error.value=e.response?.data?.message || e.response?.data?.description || 'No pudimos completar la operación. Revisa la conexión.';showError.value=true;}
async function load(){loading.value=true;error.value='';try{const [a,b,c]=await Promise.all([api.adminSummary(),api.adminCommerces(),api.adminUsers()]);summary.value=a.data;commerces.value=b.data;users.value=c.data;}catch(e){report(e);}finally{loading.value=false;}}
async function loadProducts(){loading.value=true;try{products.value=(await api.adminProducts(productCommerce.value)).data;}catch(e){report(e);}finally{loading.value=false;}}
function openCommerce(c){commerce.value=c?{...c}:{name:'',market:'San Miguelito',stall:'',phone:'',owner_id:null};commerceDialog.value=true;}
async function saveCommerce(){if(saving.value)return;saving.value=true;try{if(commerce.value.id)await api.adminUpdateCommerce(commerce.value.id,commerce.value);else await api.adminCreateCommerce(commerce.value);commerceDialog.value=false;success.value='Comercio guardado.';await load();}catch(e){report(e);}finally{saving.value=false;}}
async function saveUser(){if(saving.value)return;saving.value=true;try{await api.adminCreateUser(newUser.value);userDialog.value=false;newUser.value={type:'merchant',email:'',password:''};success.value='Cuenta creada. Ya puede iniciar sesión.';await load();}catch(e){report(e);}finally{saving.value=false;}}
async function logout(){try{await api.logout();}catch{}finally{localStorage.removeItem('token');localStorage.removeItem('refresh_token');router.replace('/login');}}
watch(section,value=>{search.value='';if(value==='products')loadProducts();});onMounted(load);
</script>
