-radius:10px;padding:21px}.stat-card>div{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:11px;color:#879577}.stat-card .v-icon{color:#a5b18f}.stat-card>strong{display:block;font-size:37px;line-height:1.2;font-weight:500;margin-top:20px}.stat-card>p{font-size:9px;color:#a3ad97;margin-top:10px}.overview-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:22px}.surface{background:#fff;border:1px solid #e1e6d8;border-radius:10px;overflow:hidden}.surface-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:24px;border-bottom:1px solid #edf0e6}.surface h2{font-size:14px!important;font-weight:500}.surface-heading button{font-size:9px;color:#7f9568}.empty{text-align:center;padding:48px 24px}.empty-symbol{display:grid;place-items:center;background:#f1f4e9;border-radius:50%;width:65px;height:65px;color:#9cac7c;margin:auto auto 20px}.empty h3{font-family:Georgia,serif!important;font-size:22px;font-weight:400}.empty p{font-size:10px;color:#96a187;margin:12px 0 24px;line-height:1.8}.empty .v-btn{font-size:9px;letter-spacing:0;text-transform:none}.platform-card{padding:29px;background:#e9edde;border:1px solid #e0e6d2;border-radius:10px}.platform-card h2{font-family:Georgia,serif!important;font-size:31px;font-weight:400;line-height:1.2;letter-spacing:-.7px;margin:15px 0}.platform-card>p:not(.eyebrow){font-size:11px;color:#819071;line-height:1.9}.platform-step{display:flex;gap:10px;align-items:center;margin-top:20px;font-size:10px;color:#748963}.platform-step .v-icon{font-size:20px}.roadmap-note{font-size:9px;color:#94a181;border-top:1px solid #d3ddc2;padding-top:17px;margin-top:24px;line-height:1.8}.commerce-row{width:100%;display:flex;text-align:left;align-items:center;gap:12px;padding:18px 24px;border-bottom:1px solid #eef1e7}.commerce-row>span:nth-child(2){flex:1}.commerce-row strong{font-size:11px;font-weight:500}.commerce-row small{display:block;font-size:9px;color:#a0aa94;margin-top:5px}.store-icon{width:35p